column8:
{
  "name": "audio_chat_qa",
  "title": "有声内容问答",
  "url": "http://{juaiagent-host}:{port}/api/v1.0/agent/stream",
  "method": "POST",
  "description": "功能：基于用户当前正在收听（或多轮指代）的有声内容上下文，调用大语言模型生成流式问答回复。支持三类上下文场景：(1)有在播内容时自动获取专辑标题、主播、当前分集集数作为上下文；(2)有多轮指代实体时直接提取标题与主播作为上下文；(3)无上下文时仅转发用户原始问题。\n适用场景：用户针对有声在播内容或上文提到的有声媒资提问，如「这本书作者是谁」「这个主播还有什么作品」「这本书一共多少集」「现在听的是第几集」「帮我介绍一下这本书」等。\n不适用场景：用户目的是搜索/播放某个有声内容（应使用audio_search）；用户想要打开有声首页/历史记录（应使用audio_page/audio_history）；用户做设备控制如暂停/下一集（应使用设备控制智能体）；用户问通用知识/天气/新闻等与在播有声内容无关的问题（应使用通用问答）。\n关联工具：有声搜索用 audio_search，直达页面用 audio_page，历史记录起播用 audio_history，通用闲聊用 general_chat。\n异常：在播信息获取失败时仅转发用户原始问题（LLM自行判断能否回答）；LLM响应超时或异常时返回兜底结束帧。\n结果使用：将流式文本逐帧拼接后作为TTS播报及文本展示给用户；若结果为finish帧则标志回答结束。",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "description": "用户的问题文本（对应 normalText），如「这本书一共多少集」「作者是谁」「帮我介绍一下这个评书」。"
      },
      "entity_info_list": {
        "type": "array",
        "description": "实体信息列表，由上游NLU指代解析下发。每个元素包含 sort(分类,hisapp=有声)、type(类型,CURRENT_PLAYING=在播)、data(媒资列表含id/thirdSongId/title/author)。当 type=CURRENT_PLAYING 时工具会自动调用 itemDetail 接口补全专辑详情和当前分集集数；当 sort=hisapp 且 type≠CURRENT_PLAYING 时直接提取标题与主播作为上下文。"
      },
      "config_map": {
        "type": "object",
        "description": "终端设备上下文参数，主要供查询 itemDetail 接口使用。关键字段：deviceid(设备ID)、hisappversion(应用版本)、license(授权码)、customerid(客户ID)。"
      },
      "word_list": {
        "type": "array",
        "description": "分词与语义标签列表，随 llmSemantic.content 透传给流式问答阶段，用于辅助模型理解用户问句上下文。"
      },
      "intention": {
        "type": "string",
        "description": "当前意图标识，固定传 audio_chat，用于流式接口路由和结果标识。",
        "enum": ["audio_chat"]
      },
      "nlu_state": {
        "type": "string",
        "description": "NLU多轮交互状态。4=需多轮但未改写直接进入问答；0~3=正常交互/已改写。",
        "enum": ["0", "1", "2", "3", "4"]
      },
      "trace_id": {
        "type": "string",
        "description": "链路追踪ID，用于日志串联和调试。"
      }
    },
    "required": ["query", "intention"]
  },
  "output": {
    "type": "object",
    "properties": {
      "phase1_response": {
        "type": "object",
        "description": "第一阶段（非流式handle接口）返回结果，告知调用方需要继续发起流式请求",
        "properties": {
          "llmSemantic": {
            "type": "object",
            "description": "语义信息",
            "properties": {
              "domain": {"type": "string", "description": "领域标识，固定为 AUDIO_TOPIC"},
              "intent": {"type": "string", "description": "意图标识，固定为 audio_chat"},
              "content": {"type": "string", "description": "透传给流式阶段的上下文JSON（含 wordList 分词信息）"},
              "isMultipleCalls": {"type": "boolean", "description": "是否需要多次调用（流式），固定为 true"}
            }
          },
          "sort": {"type": "string", "description": "一级分类，固定为 chatting"},
          "subsort": {"type": "string", "description": "二级分类，固定为 chatting"},
          "ttscontent": {"type": "string", "description": "TTS内容，问答意图下为空字符串（由流式阶段输出）"}
        }
      },
      "phase2_stream_response": {
        "type": "object",
        "description": "第二阶段（流式handleStream接口）逐帧返回结果",
        "properties": {
          "text": {"type": "string", "description": "当前帧的文本增量内容"},
          "seq_number": {"type": "integer", "description": "当前帧序号，从0递增"},
          "finish": {"type": "boolean", "description": "是否为结束帧，true 时表示回答完毕"},
          "intention": {"type": "string", "description": "意图标识，始终为 audio_chat"}
        }
      }
    },
    "usage_hint": "Phase1仅做意图确认(isMultipleCalls=true)，不携带实际回复内容；Phase2为流式文本输出，终端逐帧拼接text字段显示并送入TTS播报，finish=true时停止拼接。若问答结果为空则展示兜底话术。"
  },
  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {"type": "string", "description": "错误码。PARAM_ERROR_TEXT_REQUIRED-normalText为空；PARAM_ERROR_CONFIGMAP_REQUIRED-configMap为空；LLM_CALL_FAILED-大模型调用失败；MEDIA_INFO_FETCH_FAILED-在播信息获取失败(非阻断性,降级为无上下文问答)。"},
      "error_message": {"type": "string", "description": "错误描述信息"}
    }
  },
  "examples": [
    {
      "scenario": "针对在播有声书提问（有CURRENT_PLAYING实体）",
      "input": {
        "query": "这本书一共多少集",
        "intention": "audio_chat",
        "entity_info_list": [
          {
            "sort": "hisapp",
            "type": "CURRENT_PLAYING",
            "data": [{"id": "10001", "thirdSongId": "20001", "title": "三国演义", "author": "袁阔成"}]
          }
        ],
        "config_map": {"deviceid": "device_001", "hisappversion": "3rd.audio.700", "license": "xxx", "customerid": "cust_001"},
        "trace_id": "trace-qa-001"
      },
      "output": {
        "phase1_response": {
          "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_chat", "content": "{\"wordList\":[...]}", "isMultipleCalls": true},
          "sort": "chatting",
          "subsort": "chatting",
          "ttscontent": ""
        },
        "phase2_stream_response": [
          {"text": "《三国演义》评书由袁阔成播讲，", "seq_number": 0, "finish": false, "intention": "audio_chat"},
          {"text": "一共365集。您当前收听到第128集。", "seq_number": 1, "finish": false, "intention": "audio_chat"},
          {"text": "", "seq_number": 2, "finish": true, "intention": "audio_chat"}
        ]
      }
    },
    {
      "scenario": "多轮指代提问（有非在播指代实体）",
      "input": {
        "query": "这个主播还有什么其他作品",
        "intention": "audio_chat",
        "entity_info_list": [
          {
            "sort": "hisapp",
            "type": "REFERENCE",
            "data": [{"id": "10002", "title": "郭德纲经典相声集", "author": "郭德纲"}]
          }
        ],
        "trace_id": "trace-qa-002"
      },
      "output": {
        "phase1_response": {
          "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_chat", "content": "{\"wordList\":[...]}", "isMultipleCalls": true},
          "sort": "chatting",
          "subsort": "chatting",
          "ttscontent": ""
        },
        "phase2_stream_response": [
          {"text": "郭德纲除了《郭德纲经典相声集》外，还有", "seq_number": 0, "finish": false, "intention": "audio_chat"},
          {"text": "《郭德纲相声精选》《老郭有新番》等多部作品。", "seq_number": 1, "finish": false, "intention": "audio_chat"},
          {"text": "", "seq_number": 2, "finish": true, "intention": "audio_chat"}
        ]
      }
    },
    {
      "scenario": "无上下文的有声类提问",
      "input": {
        "query": "评书和相声有什么区别",
        "intention": "audio_chat",
        "entity_info_list": [],
        "trace_id": "trace-qa-003"
      },
      "output": {
        "phase1_response": {
          "llmSemantic": {"domain": "AUDIO_TOPIC", "intent": "audio_chat", "content": "{\"wordList\":[]}", "isMultipleCalls": true},
          "sort": "chatting",
          "subsort": "chatting",
          "ttscontent": ""
        },
        "phase2_stream_response": [
          {"text": "评书是一种传统口头讲述艺术，以说为主；相声则以说、学、逗、唱四门功课为基础，注重幽默效果。", "seq_number": 0, "finish": false, "intention": "audio_chat"},
          {"text": "", "seq_number": 1, "finish": true, "intention": "audio_chat"}
        ]
      }
    },
    {
      "scenario": "参数异常-query为空",
      "input": {"query": "", "intention": "audio_chat"},
      "output": {"error_code": "PARAM_ERROR_TEXT_REQUIRED", "error_message": "normalText不能为空"}
    }
  ]
}
